267	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
268	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
269	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
270	        "NSW", new int[] {2000, 2099},
271	        "VIC", new int[] {3000, 3099},
272	        "QLD", new int[] {4000, 4099});
273	
274	    /**
275	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
276	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
277	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
278	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
279	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
280	     */
281	    @Transient
282	    public String getRegion() {
283	        String byPostcode = regionForPostcode(this.postcode);
284	        if (byPostcode != null) {
285	            return byPostcode;
286	        }
287	        if ("Sydney".equals(this.city)) {
288	            return "NSW";
289	        }
290	        if ("Melbourne".equals(this.city)) {
291	            return "VIC";
292	        }
293	        if ("Brisbane".equals(this.city)) {
294	            return "QLD";
295	        }
296	        return "UNKNOWN";
297	    }
298	
299	    /**
300	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
301	     * customer code}: the region segment before the first '-' of the customer code
302	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
303	     * code has been assigned yet.
304	     */
305	    @Transient
306	    public String getLocality() {
307	        if (this.customerCode != null) {
308	            int dash = this.customerCode.indexOf('-');
309	            if (dash > 0) {
310	                return this.customerCode.substring(0, dash);
311	            }
312	        }
313	        return getRegion();
314	    }
315	
316	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
317	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
318	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
319	    public static int[] postcodeRangeForRegion(String region) {
320	        return REGION_POSTCODE_RANGES.get(region);
321	    }
322	
323	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
324	     *  absent, not a 4-digit value, or in no known range. */
325	    private static String regionForPostcode(String postcode) {
326	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
327	            return null;
328	        }
329	        int value = Integer.parseInt(postcode);
330	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
331	            int[] range = entry.getValue();
332	            if (value >= range[0] && value <= range[1]) {
333	                return entry.getKey();
334	            }
335	        }
336	        return null;
337	    }
338	
339	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
340	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
341	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
342	     *  {@code +1}), so a number matches at most one. */
343	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
344	        "+61", 9, "+1", 10);
345	
346	    /**
347	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
348	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
349	     * to the raw value when it is {@code null} or begins with no recognised country code.
350	     */
351	    @Transient
352	    public String getTelephoneDisplay() {
353	        if (this.telephone == null) {
354	            return null;
355	        }
356	        String countryCode = countryCodeOf(this.telephone);
357	        if (countryCode == null) {
358	            return this.telephone;
359	        }
360	        String national = this.telephone.substring(countryCode.length());
361	        StringBuilder grouped = new StringBuilder(countryCode);
362	        for (int i = 0; i < national.length(); i++) {
363	            if (i % 3 == 0) {
364	                grouped.append(' ');
365	            }
366	            grouped.append(national.charAt(i));
367	        }
368	        return grouped.toString();
369	    }
370	
371	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
372	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
373	    public static String countryCodeOf(String telephone) {
374	        if (telephone == null) {
375	            return null;
376	        }
377	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
378	            if (telephone.startsWith(countryCode)) {
379	                return countryCode;
380	            }
381	        }
382	        return null;
383	    }
384	
385	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
386	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
387	     *  {@code +1 => 10}). */
388	    public static Integer nationalNumberLength(String countryCode) {
389	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
390	    }
391	
392	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
393	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
394	     *  digit-free value yields {@code 0}. */
395	    private static int luhnCheckDigit(String value) {
396	        int sum = 0;
397	        boolean doubling = true;
398	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
399	            char c = value.charAt(i);
400	            if (c < '0' || c > '9') {
401	                continue;
402	            }
403	            int digit = c - '0';
404	            if (doubling) {
405	                digit *= 2;
406	                if (digit > 9) {
407	                    digit -= 9;
408	                }
409	            }
410	            sum += digit;
411	            doubling = !doubling;
412	        }
413	        return (10 - (sum % 10)) % 10;
414	    }
