427	    public List<Pet> getPets() {
428	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
429	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
430	        return Collections.unmodifiableList(sortedPets);
431	    }
