433	    public void setPets(List<Pet> pets) {
434	        this.pets = new HashSet<>(pets);
435	    }
436	
437	    public void addPet(Pet pet) {
438	        getPetsInternal().add(pet);
439	        pet.setOwner(this);
440	    }
