442	    /**
443	     * Return the Pet with the given name, or null if none found for this Owner.
444	     *
445	     * @param name to test
446	     * @return true if pet name is already in use
447	     */
448	    public Pet getPet(String name) {
449	        return getPet(name, false);
450	    }
451	
452	    /**
453	     * Return the Pet with the given name, or null if none found for this Owner.
454	     *
455	     * @param name to test
456	     * @return true if pet name is already in use
457	     */
458	    public Pet getPet(String name, boolean ignoreNew) {
459	        name = name.toLowerCase();
460	        for (Pet pet : getPetsInternal()) {
461	            if (!ignoreNew || !pet.isNew()) {
462	                String compName = pet.getName();
463	                compName = compName.toLowerCase();
464	                if (compName.equals(name)) {
465	                    return pet;
466	                }
467	            }
468	        }
469	        return null;
470	    }
471	
472	    public Pet getPet(Integer petId) {
473	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
474	    }
475	
476	    @Override
477	    public String toString() {
478	        return new ToStringCreator(this)
479	
480	            .append("id", this.getId())
481	            .append("new", this.isNew())
482	            .append("lastName", this.getLastName())
483	            .append("firstName", this.getFirstName())
484	            .append("address", this.address)
485	            .append("city", this.city)
486	            .append("telephone", this.telephone)
487	            .toString();
488	    }
489	}
